/*
 * A128118  At the n-th iteration the sequence of integers from n down to 1
 *          are appended to the sequence a(n) times.
 * https://oeis.org/A128118
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 555, u16 n <= 555, u32 n <= 555, u64 n <= 555,
 *            u128 n <= 555, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A128118 – Sequence generated by repeatedly appending
   the block [k, k-1, …, 1] a(k) times.
   a(1) = 1, a(2) = 2, and for k ≥ 3, a(k) is the value at
   position k of the already built sequence. */

#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == 0) return 0;                  /* safety, not used by OEIS */
    /* start with the first term */
    size_t capacity = (size_t)n * 2 + 10;   /* generous initial capacity */
    seq_t *seq = (seq_t*)malloc(capacity * sizeof(seq_t));
    if (!seq) return 0;                     /* allocation failure – unlikely */
    seq[0] = (seq_t)1;                      /* a(1) */
    size_t seq_len = 1;
    idx_t iter = 2;                         /* next k to process */

    /* iteratively build the sequence until we have at least n terms */
    while (seq_len < (size_t)n)
    {
        seq_t reps;
        if (iter == 2)                     /* a(2) is defined to be 2 */
            reps = (seq_t)2;
        else
            reps = seq[(size_t)iter - 1];   /* a(iter) already known */

        /* prepend the whole block [iter, …, 1] repeated 'reps' times */
        size_t needed = (size_t)iter * (size_t)reps;   /* size of next block */
        if (seq_len + needed > capacity)
        {
            capacity = seq_len + needed + 10;
            seq = (seq_t*)realloc(seq, capacity * sizeof(seq_t));
            if (!seq) return 0;           /* allocation failure */
        }

        for (idx_t r = 0; r < reps; ++r)
            for (idx_t v = iter; v >= 1; --v)
                seq[seq_len++] = (seq_t)v;

        ++iter;
    }

    seq_t result = seq[n - 1];
    free(seq);
    return result;
}
